function EmployeeManagementView(){
 const [rows,setRows]=React.useState(sampleEmployees),[q,setQ]=React.useState(""),[modal,setModal]=React.useState(false),[editing,setEditing]=React.useState<any>(null),[form,setForm]=React.useState({name:"",email:"",phone:"",role:"Staff"}),[error,setError]=React.useState(""),[notice,setNotice]=React.useState("");
 const filtered=rows.filter(x=>(x.name+" "+x.email+" "+x.role).toLowerCase().includes(q.toLowerCase()));
 const open=(x?:any)=>{setEditing(x||null);setForm({name:x?.name||"",email:x?.email||"",phone:x?.phone||"",role:x?.role||"Staff"});setError("");setNotice("");setModal(true)};
 const save=()=>{const name=form.name.trim(),email=form.email.trim();if(!name||!email){setError("Employee name and email are required.");return}if(rows.some(x=>x.id!==editing?.id&&x.email.toLowerCase()===email.toLowerCase())){setError("An employee with this email already exists.");return}if(editing){setRows(old=>old.map(x=>x.id===editing.id?{...x,...form,name,email}:x));setNotice("Employee details updated in this prototype.");}else{setRows(old=>[...old,{id:"EMP-"+String(old.length+1).padStart(3,"0"),...form,name,email,status:"Invited"}]);setNotice("Employee added as Invited in this prototype.");}setModal(false);setEditing(null);setForm({name:"",email:"",phone:"",role:"Staff"});setError("")};
 const changeStatus=(x:any)=>{if(x.status==="Invited"){setNotice("Resending invitations requires backend integration.");return}setRows(old=>old.map(y=>y.id===x.id?{...y,status:y.status==="Active"?"Inactive":"Active"}:y))};
 return <><div className="im-head"><div><h1 className="im-title">Employee Management</h1><p className="im-sub">Manage workspace access, employee roles and account status.</p></div><button className="im-btn primary" onClick={()=>open()}>＋ Add Employee</button></div>
 <div className="im-stats"><div className="im-stat"><label>Total Employees</label><strong>{rows.length}</strong><small>Workspace accounts</small></div><div className="im-stat"><label>Active</label><strong>{rows.filter(x=>x.status==="Active").length}</strong><small>Can access the workspace</small></div><div className="im-stat"><label>Invited</label><strong>{rows.filter(x=>x.status==="Invited").length}</strong><small>Awaiting account activation</small></div><div className="im-stat"><label>Inactive</label><strong>{rows.filter(x=>x.status==="Inactive").length}</strong><small>Access disabled</small></div></div>
 <section className="im-panel"><div className="im-panel-head"><div><h2 className="im-panel-title">Employees</h2><p className="im-panel-sub">Assign only the access required for each employee's responsibilities.</p></div></div><div className="im-tools"><input className="im-input im-search" placeholder="Search name, email or role..." value={q} onChange={e=>setQ(e.target.value)}/><button className="im-btn" onClick={()=>setQ("")}>Clear</button></div>
 <div className="im-desktop-table"><table className="im-table" style={{minWidth:820}}><thead><tr><th>EMPLOYEE</th><th>CONTACT</th><th>ROLE</th><th>STATUS</th><th>ACTIONS</th></tr></thead><tbody>{filtered.map(x=><tr key={x.id}><td><span className="im-primary-cell">{x.name}</span><span className="im-secondary">{x.id}</span></td><td>{x.email}<span className="im-secondary">{x.phone||"No phone"}</span></td><td>{x.role}</td><td><span className={"im-pill "+(x.status==="Active"?"ok":x.status==="Invited"?"active":"out")}>{x.status}</span></td><td><div className="im-actions"><button className="im-link" onClick={()=>open(x)}>Edit</button><button className="im-link" onClick={()=>changeStatus(x)}>{x.status==="Invited"?"Resend Invite":x.status==="Active"?"Deactivate":"Activate"}</button></div></td></tr>)}</tbody></table></div>
 <div className="im-mobile-cards">{filtered.map(x=><div className="im-card" key={x.id}><div className="im-card-top"><div><div className="im-card-name">{x.name}</div><div className="im-card-meta">{x.email}</div></div><span className={"im-pill "+(x.status==="Active"?"ok":x.status==="Invited"?"active":"out")}>{x.status}</span></div><div className="im-card-grid"><div><label>Role</label><strong>{x.role}</strong></div><div><label>Phone</label><strong>{x.phone||"—"}</strong></div></div><div className="im-card-actions"><button className="im-link" onClick={()=>open(x)}>Edit</button><button className="im-link" onClick={()=>changeStatus(x)}>{x.status==="Invited"?"Resend Invite":x.status==="Active"?"Deactivate":"Activate"}</button></div></div>)}</div>{!filtered.length&&<div className="im-empty">No employees found.</div>}</section>
 <section className="im-panel"><div className="im-panel-head"><div><h2 className="im-panel-title">Role Overview</h2><p className="im-panel-sub">Suggested role separation for the inventory workflow.</p></div></div><div className="im-role-grid"><div><b>Administrator</b><p>Manage employees, settings, categories and all workspace operations.</p></div><div><b>Inventory Manager</b><p>Manage inventory configuration and record or review stock transactions.</p></div><div><b>Staff</b><p>Record permitted daily transactions and view relevant inventory information.</p></div></div></section>
 {notice&&<div className="im-save-note">{notice}</div>}<p className="im-footer-note">Prototype only · Invitations, authentication and permission enforcement require backend integration.</p>
 {modal&&<Modal title={editing?"Edit Employee":"Add Employee"} onClose={()=>setModal(false)} footer={<><button className="im-btn" onClick={()=>setModal(false)}>Cancel</button><button className="im-btn primary" onClick={save}>{editing?"Save Changes":"Send Invitation"}</button></>}><div className="im-modal-body"><Field label="Employee name" full><input value={form.name} onChange={e=>setForm({...form,name:e.target.value})} placeholder="Full name"/></Field><Field label="Email address" full><input type="email" value={form.email} onChange={e=>setForm({...form,email:e.target.value})} placeholder="employee@example.com"/></Field><Field label="Phone (optional)"><input value={form.phone} onChange={e=>setForm({...form,phone:e.target.value})} placeholder="+251..."/></Field><Field label="Role"><select value={form.role} onChange={e=>setForm({...form,role:e.target.value})}><option>Staff</option><option>Inventory Manager</option><option>Administrator</option></select></Field>{error&&<div className="im-field full"><span style={{color:"#1E293B",fontSize:10}}>{error}</span></div>}<div className="im-field full"><p className="im-callout">{editing?"Role and contact details are editable in this prototype.":"The employee will appear as Invited in this prototype. No real invitation email or user account is created."}</p></div></div></Modal>}
 </>}
function ReportsWorkspace(){return <div className="im-root"><style>{css}</style><ReportsView/></div>}

export default ReportsWorkspace
